// Фикстура проверки частичной коллизии тайла и логических координат (§42).
// Текстуры здесь не нужны: проверяются данные, тела и запросы, а не картинка.
$.ready(() => {
    // Стены мира не ставим (solid: false): они бы перехватывали лучи и падение.
    $.world.gravity(0, 1400).color('#101820').bounds(0, 0, 2560, 1440, { solid: false });

    // 4×3 клетки по 32 px, центр (0,0) → x -64..64, y -48..48.
    // Тайл 7 — тонкая платформа: visual 32×32, тело — полоса [-16,8]..[16,16],
    // то есть верхние 24 px клетки пусты для тела и луча.
    // Тайл 1 — полная клетка (земля).
    $.tilemap.create({
        id: 'geom',
        src: 'assets/atlas.png',
        tile: 32,
        cols: 4,
        data: [
            '....',
            '.7..',
            '11..',
        ],
        tiles: {
            1: { shape: 'full' },
            7: { shape: [-16, 8, 16, 16] },
        },
    }).at(0, 0);

    // Логические координаты: буфер с рамкой со всех сторон, origin сдвинут на
    // padding, поэтому клетка x=-1 лежит ВНУТРИ буфера (см. docs §14).
    $('<tilemap>', {
        id: 'pad',
        tile: 32,
        cols: 2,
        rows: 2,
        data: [0, 0, 0, 0],
        mapW: 2,
        mapH: 2,
        pad: [1, 1, 1, 1],
        origin: [0, 0],
        tiles: { 1: { shape: 'full' } },
    }).at(0, 600);

    // Падает на тонкую платформу: клетка (1,1) занимает x -32..0, y -16..16,
    // полоса — нижние 8 px клетки, её верх — y = 8. Тело 24×24 встанет
    // центром на y = -4 (низ тела ровно на верхней границе полосы).
    $('<player>', { id: 'hero' }).at(-16, -120).size(24, 24).appendTo($.world);
});
